'use client';

import Image from 'next/image';
import styles from './login.module.css';
import { useState } from 'react';
import { useAuth } from './AuthProvider';
import { useRouter } from 'next/navigation';
import { toast } from "@/components/ui/use-toast";
import { Loader2, Eye, EyeOff } from 'lucide-react';

export function LoginForm() {
    const router = useRouter();
    const { setUser } = useAuth();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [submitting, setSubmitting] = useState(false);
    const [showPassword, setShowPassword] = useState(false);

    const handleSubmit = async () => {
        if (!email || !password) {
            toast({
                variant: "destructive",
                title: "Missing details",
                description: "Please enter email and password.",
            });
            return;
        }

        try {
            setSubmitting(true);
            const res = await fetch('/api/auth/login', {
                method: 'POST',
                body: JSON.stringify({ email, password }),
                headers: { 'Content-Type': 'application/json' },
            });

            const data = await res.json();
            if (!res.ok) {
                toast({
                    variant: "destructive",
                    title: "Login failed",
                    description: data.message ?? "Invalid email or password.",
                });
                return;
            }

            setUser(data.user);
            toast({
                variant: "success",
                title: "Welcome back",
                description: "Logged in successfully.",
            });
            router.push('/dashboard');
        } catch {
            toast({
                variant: "destructive",
                title: "Network error",
                description: "Please try again.",
            });
        } finally {
            setSubmitting(false);
        }
    };

    return (
        <div className={styles.container}>
            <div className={styles.bgLogo} aria-hidden>
                <Image
                    src="/IshmaalQuran-Logo.png"
                    alt=""
                    fill
                    priority
                    sizes="(max-width: 768px) 520px, 720px"
                    className={styles.bgLogoImg}
                />
            </div>

            <header className={styles.header}>
                <div className={styles.logoWrap} aria-hidden>
                    <Image
                        src="/IshmaalQuran-Logo.png"
                        alt=""
                        width={64}
                        height={64}
                        priority
                        className={styles.logo}
                    />
                </div>
                <p className={styles.appTitle}>Live with Quran</p>
                <h1 className={styles.title}>Welcome</h1>
                <p className={styles.subtitle}>Sign in to continue your learning journey.</p>
            </header>

            <div className={styles.card}>
                <div className={styles.fieldGroup}>
                    <label htmlFor="email" className={styles.label}>
                        Email
                    </label>
                    <input
                        id="email"
                        type="email"
                        autoComplete="email"
                        placeholder="you@example.com"
                        className={styles.input}
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        required
                    />
                </div>

                <div className={styles.fieldGroup}>
                    <label htmlFor="password" className={styles.label}>
                        Password
                    </label>
                    <div className={styles.passwordContainer}>
                        <input
                            id="password"
                            type={showPassword ? 'text' : 'password'}
                            autoComplete="current-password"
                            placeholder="••••••••"
                            className={`${styles.input} ${styles.passwordInput}`}
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            required
                        />
                        <button
                            type="button"
                            className={styles.toggleButton}
                            onClick={() => setShowPassword((prev) => !prev)}
                            aria-label={showPassword ? 'Hide password' : 'Show password'}
                        >
                            {showPassword ? (
                                <EyeOff size={20} aria-hidden />
                            ) : (
                                <Eye size={20} aria-hidden />
                            )}
                        </button>
                    </div>
                </div>

                <button
                    type="button"
                    className={styles.submitButton}
                    disabled={submitting}
                    onClick={handleSubmit}
                >
                    {submitting ? (
                        <>
                            <Loader2 className={styles.loadingIcon} aria-hidden />
                            Logging in...
                        </>
                    ) : (
                        'Login'
                    )}
                </button>
            </div>

            <p className={styles.footerLink}>
                <span className={styles.footerLinkText}>
                    Live with Quran <span className={styles.footerLinkBold}>Admin</span>
                </span>
            </p>
        </div>
    );
}